package com.brobot.future.simulation

import com.brobot.future.model.*

/**
 * "BROBOT INTELLIGENCE": template-based explanations generated by local rules.
 * This is NOT a language model and the UI says so. Every part is tagged with its [EvidenceKind].
 */
object ExplainerEngine {

    val questions: List<String> = listOf(
        "Why is this pathway shown?",
        "What assumption is being made?",
        "What should I do first?",
        "What changes if I enable protection?",
        "What does this simulation not know?"
    )

    fun answer(question: String, result: SimulationResult): ExplainerAnswer {
        val parts = mutableListOf<Assumption>()
        val scenario = result.scenario
        val rules = ScenarioCatalog.rulesFor(scenario.id)

        when (question) {
            questions[0] -> {
                if (result.riskStepCount == 0) {
                    parts += Assumption(
                        EvidenceKind.RULE,
                        "No risk steps are shown for “${scenario.title}” because none of its documented rules match the current demo profile."
                    )
                } else {
                    parts += Assumption(
                        EvidenceKind.RULE,
                        "“${scenario.title}” shows ${result.riskStepCount} possible step(s) because these documented rules matched:"
                    )

                    rules.filter {
                        it.requires(result.profile) && !it.step.isTrigger
                    }.forEach {
                        parts += Assumption(
                            EvidenceKind.RULE,
                            "${it.step.title} — ${it.ruleText}"
                        )
                    }
                }

                result.profile.let { p ->
                    scenario.readsConditions.forEach { c ->
                        parts += Assumption(
                            EvidenceKind.USER_INPUT,
                            "${c.label}: ${conditionStateLabel(c, p)}."
                        )
                    }
                }

                parts += Assumption(
                    EvidenceKind.SYNTHETIC,
                    "The profile is synthetic demo data, not read from your device."
                )
            }

            questions[1] -> {
                result.steps
                    .flatMap { it.assumptions }
                    .distinctBy { it.text }
                    .forEach {
                        parts += it
                    }

                if (result.steps.isEmpty()) {
                    parts += Assumption(
                        EvidenceKind.RULE,
                        "No steps are active, so no step-level assumptions apply."
                    )
                }

                parts += Assumption(
                    EvidenceKind.UNKNOWN,
                    "Real-world likelihood and impact are not modelled."
                )
            }

            questions[2] -> {
                val first = result.suggestedInterventions.firstOrNull()

                if (first == null) {
                    parts += Assumption(
                        EvidenceKind.SUGGESTION,
                        "In this scenario the relevant demo protections are already set. Try another scenario or reset the demo profile."
                    )
                } else {
                    parts += Assumption(
                        EvidenceKind.SUGGESTION,
                        "First: ${first.title}. ${first.description}"
                    )

                    parts += Assumption(
                        EvidenceKind.RULE,
                        "It is listed first because it matches a condition read by this scenario's rules and is not yet set in the demo profile."
                    )

                    result.suggestedInterventions.drop(1).forEach {
                        parts += Assumption(
                            EvidenceKind.SUGGESTION,
                            "Then: ${it.title}."
                        )
                    }
                }

                parts += Assumption(
                    EvidenceKind.UNKNOWN,
                    "Which action matters most for a real person depends on facts this simulation does not have."
                )
            }

            questions[3] -> {
                val first = result.suggestedInterventions.firstOrNull()

                if (first == null) {
                    parts += Assumption(
                        EvidenceKind.RULE,
                        "No further demo protection would change this scenario's pathway."
                    )
                } else {
                    val cmp = SimulationEngine.compare(
                        scenario.id,
                        result.profile,
                        first
                    )

                    parts += Assumption(
                        EvidenceKind.SUGGESTION,
                        "If you applied “${first.title}”: ${cmp.changeDescription}"
                    )

                    parts += Assumption(
                        EvidenceKind.RULE,
                        cmp.summary
                    )

                    parts += Assumption(
                        EvidenceKind.RULE,
                        "Possible steps: ${cmp.before.riskStepCount} → ${cmp.after.riskStepCount}."
                    )
                }

                parts += Assumption(
                    EvidenceKind.UNKNOWN,
                    "Other risks may remain; this simulation does not estimate probabilities."
                )
            }

            else -> {
                parts += Assumption(
                    EvidenceKind.UNKNOWN,
                    "Your real devices, accounts, apps, networks and habits — nothing real is inspected."
                )

                parts += Assumption(
                    EvidenceKind.UNKNOWN,
                    "Whether any real weakness or breach exists. BROBOT does not detect breaches."
                )

                parts += Assumption(
                    EvidenceKind.UNKNOWN,
                    "How likely or how severe any pathway would be in reality. No probabilities are produced."
                )

                parts += Assumption(
                    EvidenceKind.SYNTHETIC,
                    "Everything shown comes from synthetic scenario data and a local rules engine — no live AI model generated this text."
                )
            }
        }

        return ExplainerAnswer(question, parts)
    }

    /** Explains exactly which documented rules produced (or hid) each step of the current chain. */
    fun explainChain(result: SimulationResult): List<Pair<String, String>> {
        val rules = ScenarioCatalog.rulesFor(result.scenario.id)
        val shown = rules.filter { it.requires(result.profile) }
        val hidden = rules.filter { !it.requires(result.profile) }

        return listOf(
            "Hypothetical and conditional" to
                "This chain is a what-if. It does not mean any of these steps has happened or will happen, and no real compromise was detected.",

            "Steps shown (rule matched)" to
                (
                    if (shown.isEmpty()) {
                        "None."
                    } else {
                        shown.joinToString("\n") {
                            "• ${it.step.title} — ${it.ruleText}"
                        }
                    }
                ),

            "Steps not shown (rule not matched)" to
                (
                    if (hidden.isEmpty()) {
                        "None — every rule matched."
                    } else {
                        hidden.joinToString("\n") {
                            "• ${it.step.title} — ${it.ruleText}"
                        }
                    }
                ),

            "What is not known" to
                "Real-world likelihood, timing and impact. Everything uses synthetic data and a local rules engine, not a live AI model."
        )
    }
}
